import { describe, it, expect } from 'vitest';
import { parseGcodeHeader } from '../../../../../src/kernel/export/gcode/gcodeHeaderParser';

const FIXTURE = `
; HEADER_BLOCK_START
; generated by OrcaSlicer 2.4.2 on 2026-09-14 at 10:03:13
; total layer number: 100
; filament_density: 1.24
; max_z_height: 20.00
; filament: 1
; HEADER_BLOCK_END
G28 ; home
G1 X0 Y0 Z0.2
; total filament used [g] = 3.86
; total layers count = 100
; estimated printing time (normal mode) = 19m 33s
; estimated first layer printing time (normal mode) = 2s
; filament used [mm] = 1295.40
; filament used [cm3] = 3.12
; filament used [g] = 3.86
`;

describe('parseGcodeHeader', () => {
  it('parses estimated print time from "Xh Ym Zs" style durations', () => {
    const stats = parseGcodeHeader(FIXTURE);
    expect(stats.estimatedPrintTimeSeconds).toBe(19 * 60 + 33);
  });

  it('parses filament mass, length, layer count, and max Z', () => {
    const stats = parseGcodeHeader(FIXTURE);
    expect(stats.filamentUsedGrams).toBe(3.86);
    expect(stats.filamentUsedMeters).toBeCloseTo(1.2954, 4);
    expect(stats.layerCount).toBe(100);
    expect(stats.maxZMm).toBe(20);
  });

  it('parses an hours+minutes+seconds duration', () => {
    const stats = parseGcodeHeader('; estimated printing time (normal mode) = 1h 2m 3s\n');
    expect(stats.estimatedPrintTimeSeconds).toBe(3600 + 120 + 3);
  });

  it('returns an empty object for gcode with no recognizable header', () => {
    const stats = parseGcodeHeader('G28\nG1 X0 Y0\n');
    expect(stats).toEqual({});
  });
});

// Header vocabulary: OrcaSlicer commit 95d3e8eafc8cea23f022700be01c5f02ab26c939
// src/libslic3r/GCode.cpp and Utils.hpp; fixtures reproduce metadata only.
describe('validated slicer metadata', () => {
  it('sums all slots and prefers the independent total mass', () => {
    const slots = parseGcodeHeader('; filament used [g] = 2.1, 0, 3.2\n; filament used [mm] = 1000, 0, 2500');
    expect(slots.filamentUsedGrams).toBeCloseTo(5.3, 8);
    expect(slots.filamentUsedMeters).toBe(3.5);
    expect(parseGcodeHeader('; filament used [g] = 2.1, 3.2\n; total filament used [g] = 5.4')).toMatchObject({filamentUsedGrams: 5.4});
  });
  it('handles fractional seconds and days without accepting partial durations', () => {
    expect(parseGcodeHeader('; estimated printing time = 0.500000s').estimatedPrintTimeSeconds).toBe(0.5);
    expect(parseGcodeHeader('; estimated printing time = 1d 2h 3m 4s').estimatedPrintTimeSeconds).toBe(93784);
    expect(parseGcodeHeader('; estimated printing time = 1h nonsense')).toEqual({});
    expect(parseGcodeHeader('; estimated printing time = -3s')).toEqual({});
  });
  it('reports header identity and normal-mode precedence', () => {
    expect(parseGcodeHeader('; generated by PrusaSlicer 2.9.4+linux on 2026-10-11\r\n; estimated printing time (silent mode) = 2h\r\n; estimated printing time = 4h\r\n; estimated printing time (normal mode) = 1h')).toEqual({slicer: {name:'PrusaSlicer', version:'2.9.4+linux'}, estimatedPrintTimeSeconds:3600});
    expect(parseGcodeHeader('; model printing time: 1m; total estimated time: 2m')).toEqual({estimatedPrintTimeSeconds:120});
  });
  it.each(['; filament used [g] = 3.86broken', '; filament used [g] = 1, bad, 2', '; filament used [mm] = 1,', '; filament used [g] = -2', '; total layers count = 100invalid', '; total layers count = 2.5', '; max_z_height: 3broken', 'G1 X0 ; filament used [g] = 100', '; foo = estimated printing time = 1h'])('omits invalid or non-metadata input %s', text => {
    expect(parseGcodeHeader(text)).toEqual({});
  });
});


describe('nonfinite metadata', () => {
  it('omits overflow and invalid explicit totals without substituting partial slots', () => {
    const huge = '9'.repeat(400);
    expect(parseGcodeHeader(`; filament used [g] = ${huge}\n; estimated printing time = ${huge}s\n; max_z_height: ${huge}\n; total layers count = ${huge}`)).toEqual({});
    expect(parseGcodeHeader('; total filament used [g] = broken\n; filament used [g] = 2, 3')).toEqual({});
  });
});
